+        public static List<ProgressBarNode> FillBarNodesData(List<ProgressBarNode> progressBarNodeList, List<FlowInstanceOperationHistory> sFlowNodeList, FlowInstance sFlowInstance, bool isService)
+        {
+
+            if (sFlowNodeList != null && sFlowNodeList.Any() && sFlowInstance != null)
+            {
+                sFlowNodeList = sFlowNodeList.OrderByDescending(a => a.CreateDate).ToList();
+                var lastNode = sFlowNodeList.FirstOrDefault(x => x.InstanceId == sFlowInstance.Id);//最后节点
+                var currentNode = sFlowInstance.ActivityName;
+
+                if (!isService)
+                {
+                    //如果是报销流程 的 总经理审批 ，需重新赋值
+                    sFlowNodeList.ForEach(a =>
+                    {
+                        a.Content = GetCurrentContent(a.Content);
+                    });
+
+                    currentNode = GetCurrentNode(currentNode);
+                }
+
+                var nodeEnum = Tools.ReimburseFlowNodeByName(currentNode);
+
+                progressBarNodeList = ProgressBarNodeListProcess(progressBarNodeList, sFlowNodeList, currentNode, isService, nodeEnum, lastNode);
+            }
+
+            return progressBarNodeList;
+
+        }
