+        /// <param name="nodeEnum"></param>
+        /// <param name="lastNode"></param>
+        private static List<ProgressBarNode> ProgressBarNodeListProcess(List<ProgressBarNode> progressBarNodeList, List<FlowInstanceOperationHistory> sFlowNodeList, string currentNode, bool isService, ReimburseFlowNode nodeEnum, FlowInstanceOperationHistory lastNode)
+        {
+            progressBarNodeList.ForEach(a =>
+            {
+                var flowNode = sFlowNodeList.FirstOrDefault(x => x.Content == a.Name);
+                var totalTime = sFlowNodeList?.Where(x => x.Content == a.Name).Sum(a => a.IntervalTime);
+
+                if (isService && a.Name == ServiceOrderFlowNodeNameConsts.Outbound)
+                {
+                    flowNode = sFlowNodeList.FirstOrDefault(x => x.Content == ServiceOrderFlowNodeNameConsts.OutboundStart);
+
+                    totalTime = sFlowNodeList?.Where(x => x.Content == ServiceOrderFlowNodeNameConsts.OutboundStart).Sum(a => a.IntervalTime);
+
+                    //同名称节点的时间总计
+                    a.IntervalTime = totalTime;
+                    a.CreateTime = sFlowNodeList.Where(f => f.Content == a.Name)?.OrderBy(a => a.CreateDate)?.FirstOrDefault()?.CreateDate;
+                }
+
+                if (flowNode != null && flowNode.Content == a.Name)
+                {
+                    //同名称节点的时间总计
+                    a.IntervalTime = totalTime;
+                    a.CreateTime = sFlowNodeList.Where(f => f.Content == a.Name)?.OrderBy(a => a.CreateDate)?.FirstOrDefault()?.CreateDate;
+                }
+
+
+                if (a.Value < (int)nodeEnum)
+                {
+                    //设置当前节点前的节点为已审核
+                    a.IsPass = true;
+                }
+
+                if (a.Name == currentNode)
+                {
+                    //设置当前节点
+                    a.IsCurrentNode = true;
+                    //设置当前节点停留时间
+                    var currentTime = (int)(DateTime.UtcNow - lastNode.CreateDate).TotalSeconds;
+                    a.IntervalTime = totalTime + currentTime;
+                }
+            });
+
+            return progressBarNodeList;
+        }
