+
+                ["客服审批"]
+                    = Tools.ReimburseFlowNodeName(ReimburseFlowNode.CsSupervisorApproval),
+
+                ["结束"]
+                    = Tools.ReimburseFlowNodeName(ReimburseFlowNode.ReimburseEnd)
+            };
+
+            // 执行转换
+            if (nodeMapping.TryGetValue(currentNode, out var mappedNode))
+            {
+                currentNode = mappedNode;
