+        /// <summary>
+        /// 将借款状态，流程转换成报销单相应状态
+        /// </summary>
+        /// <param name="financeLoan">借款申请</param>
+        /// <param name="assistantProcessName">助理流程名称</param>
+        /// <param name="managerProcessName">经理流程名称</param>
+        /// <param name="endProcessName">结束流程名称</param>
+        /// <returns>报销单状态</returns>
+        public static int ConvertFinanceLoanStatusToReimburseStatus(FinanceLoan financeLoan, string assistantProcessName, string managerProcessName, string endProcessName)
+        {
+            if (financeLoan.Status == FinanceLoanStatus.Reject)
+            {
+                return (int)EnumRemburseStatus.RejectApproval;
+            }
+            else if (financeLoan.Status == FinanceLoanStatus.ReCall)
+            {
+                return (int)EnumRemburseStatus.WithdrawApproval;
+            }
+
+            if (financeLoan.CurrentProcess != "结束")
+            {
+                return financeLoan.CurrentProcess switch
+                {
+                    _ when financeLoan.CurrentProcess == assistantProcessName => (int)EnumRemburseStatus.AssistantApproval,
+                    _ when financeLoan.CurrentProcess == managerProcessName => (int)EnumRemburseStatus.GeneralManagerApproval,
+                    _ when financeLoan.CurrentProcess == endProcessName => (int)EnumRemburseStatus.EndApproval,
+                    _ => 0,
+                };
+            }
+            else
+            {
+                return financeLoan.Status.Value switch
+                {
