+        /// <returns></returns>
+        public static (decimal,decimal) GetAmountPerDay(int totalDailyReportDays, decimal amount,decimal amountLC)
+        {
+            var amountPerDay = totalDailyReportDays == 0 ? amount : Math.Round(amount / totalDailyReportDays, 2);
+            var amountPerDayLC = totalDailyReportDays == 0 ? amountLC : Math.Round(amountLC / totalDailyReportDays, 2);
