+        public static (decimal,decimal) CalculateCorporatePaymentFromDataWithCache(
+            ReimburseInfo reimburseInfo,
+            string currency,
+            List<ExhibitionMeiyaRel> exhibitionMeiyaRels,
+            Dictionary<string, ReimburseCommonService.ParsedMeiyaOrderData> parsedMeiyaDataCache,
+            Dictionary<(DateTime date, string currency), decimal> ratesCache)
+        {
+            var meiyaRels = new List<ExhibitionMeiyaRel>();
+            if (reimburseInfo.FromType == 2)
+            {
+                meiyaRels = exhibitionMeiyaRels.Where(p => p.ExhibitionUserNo == reimburseInfo.FromCode).ToList();
+            }
+            else if (reimburseInfo.FromType == 1)
+            {
+                meiyaRels = exhibitionMeiyaRels.Where(p => p.ServiceOrderId == reimburseInfo.ServiceOrderSapId).ToList();
+            }
+            decimal amount = 0;
+            decimal amountLC = 0;
+
+            foreach (var meiyaRel in meiyaRels)
+            {
+                if (!parsedMeiyaDataCache.TryGetValue(meiyaRel.MeiyaOrderNo, out var parsedData))
+                {
+                    continue;
+                }
+
+                if (!parsedData.OrderAmount.HasValue || string.IsNullOrEmpty(parsedData.OpDateString))
+                {
+                    continue;
+                }
+
+                if (currency == "RMB")
+                {
+                    amount += parsedData.OrderAmount.Value;
+                }
+                else
+                {
+                    DateTime opDate = DateTime.ParseExact(parsedData.OpDateString, timeString, CultureInfo.InvariantCulture);
+                    var rateCalculateResp = ReimburseCommonService.CalculateReimbursementAmountFromCache("RMB", currency, opDate, parsedData.OrderAmount.Value, ratesCache);
+                    amount += rateCalculateResp.ReimbursementAmount;
+                }
+                amountLC += parsedData.OrderAmount.Value;
+            }
+            return (amount,amountLC);
