+                else if (TrainOrderTypes.Contains(meiyaRel.MeiyaOrderType))
+                {
+                    var dataInfo = JsonConvert.DeserializeObject<MeiyaTrainOrderPushDataDto>(meiyaRel.DataJson);
+                    if (dataInfo == null) return null;
