+        /// <summary>
+        /// 批量获取汇率数据
+        /// </summary>
+        /// <param name="dates">日期列表</param>
+        /// <param name="currencies">币种列表</param>
+        /// <returns>汇率字典，key为(DateTime日期, string币种)，value为汇率</returns>
+        public async Task<Dictionary<(DateTime date, string currency), decimal>> GetExchangeRatesBatch(List<DateTime> dates, List<string> currencies)
+        {
+            var result = new Dictionary<(DateTime, string), decimal>();
+            if (dates == null || dates.Count == 0 || currencies == null || currencies.Count == 0)
+            {
+                return result;
+            }
+
+            // 去重并标准化日期
+            var uniqueDates = dates.Select(d => d.Date).Distinct().ToList();
+            var uniqueCurrencies = currencies.Distinct().ToList();
+
+            // 一次性查询所有需要的汇率
+            var rates = await UnitWork.Find<FinanceOrtt>(x => uniqueDates.Contains(x.RateDate.Date) && uniqueCurrencies.Contains(x.Currency))
+                .Select(x => new { x.RateDate, x.Currency, x.Rate })
+                .ToListAsync();
+
+            foreach (var rate in rates)
+            {
+                result[(rate.RateDate.Date, rate.Currency)] = rate.Rate;
+            }
+
+            // RMB 的汇率固定为 1
+            foreach (var date in uniqueDates)
+            {
+                result[(date, "RMB")] = 1;
+            }
+
+            return result;
+        }
