+        /// <summary>
+        /// 从预加载的汇率数据计算报销金额
+        /// </summary>
+        /// <param name="initialDocCur">原币种</param>
+        /// <param name="targetDocCur">目标币种</param>
+        /// <param name="docDate">日期</param>
+        /// <param name="initialDocAmount">原金额</param>
+        /// <param name="ratesCache">汇率缓存字典</param>
+        /// <returns>计算结果</returns>
+        public static CalculateReimbursementAmountResp CalculateReimbursementAmountFromCache(
+            string initialDocCur,
+            string targetDocCur,
+            DateTime docDate,
+            decimal initialDocAmount,
+            Dictionary<(DateTime date, string currency), decimal> ratesCache)
+        {
+            var dateKey = docDate.Date;
+
+            // 从缓存获取汇率，如果不存在则使用默认值1
+            decimal initialRateValue = ratesCache.TryGetValue((dateKey, initialDocCur), out var initialRate) ? initialRate : 1;
+            decimal targetRateValue = ratesCache.TryGetValue((dateKey, targetDocCur), out var targetRate) ? targetRate : 1;
+
+            decimal rate = initialRateValue / targetRateValue;
+            decimal reimbursementAmount = initialDocAmount * rate;
+
+            return new CalculateReimbursementAmountResp
+            {
+                Rate = rate,
+                ReimbursementAmount = Math.Round(reimbursementAmount, 2),
+                LocalCurrencyRate = initialRateValue,
+                LocalCurrencyAmount = Math.Round(initialDocAmount * initialRateValue, 2)
+            };
+        }
